routerAdd('GET', '/api/horizon/leave/employees/{id}/photo', (e) => require(`${__hooks}/lib/leave.js`).employeePhoto(e), $apis.requireAuth('core_users'))
routerAdd('GET', '/api/horizon/leave/choices', (e) => require(`${__hooks}/lib/leave.js`).choices(e), $apis.requireAuth('core_users'))
routerAdd('GET', '/api/horizon/leave/requests', (e) => require(`${__hooks}/lib/leave.js`).list(e), $apis.requireAuth('core_users'))
routerAdd('GET', '/api/horizon/leave/requests/{id}', (e) => require(`${__hooks}/lib/leave.js`).record(e), $apis.requireAuth('core_users'))
routerAdd('POST', '/api/horizon/leave/requests', (e) => require(`${__hooks}/lib/leave.js`).save(e), $apis.requireAuth('core_users'))
routerAdd('POST', '/api/horizon/leave/requests/{id}/transition', (e) => require(`${__hooks}/lib/leave.js`).transition(e), $apis.requireAuth('core_users'))
routerAdd('POST', '/api/horizon/leave/preview', (e) => require(`${__hooks}/lib/leave.js`).preview(e), $apis.requireAuth('core_users'))
routerAdd('GET', '/api/horizon/leave/allocations', (e) => require(`${__hooks}/lib/leave.js`).allocations(e), $apis.requireAuth('core_users'))
routerAdd('POST', '/api/horizon/leave/allocations', (e) => require(`${__hooks}/lib/leave.js`).allocate(e), $apis.requireAuth('core_users'))
routerAdd('POST', '/api/horizon/leave/settings', (e) => require(`${__hooks}/lib/leave.js`).settings(e), $apis.requireAuth('core_users'))
routerAdd('GET', '/api/horizon/leave/calendar', (e) => require(`${__hooks}/lib/leave.js`).calendar(e), $apis.requireAuth('core_users'))
onRecordDelete(() => { throw new BadRequestError('L’historique des congés doit être conservé.') }, 'leave_requests', 'leave_allocations', 'leave_types', 'leave_settings')
onRecordUpdate(() => { throw new BadRequestError('Corrigez une allocation par une nouvelle écriture.') }, 'leave_allocations')

routerAdd('GET', '/api/horizon/leave/balances', (e) => require(`${__hooks}/lib/leave.js`).balances(e), $apis.requireAuth('core_users'))
onRecordUpdate((e) => {
  const before = e.record.original()
  if (e.record.getString('code') !== before.getString('code') || e.record.getBool('tracked') !== before.getBool('tracked')) throw new BadRequestError('Le code et le mode de compteur sont structurels et doivent préserver l’historique.')
  e.next()
}, 'leave_types')
